CREATE FUNCTION public.guard_swap_snooze() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.snoozed_until IS NOT NULL THEN RAISE EXCEPTION 'New requests cannot be snoozed'; END IF; IF TG_OP='UPDATE' AND NEW.snoozed_until IS DISTINCT FROM OLD.snoozed_until AND (auth.uid() IS DISTINCT FROM OLD.target_id OR OLD.status<>'pending' OR NEW.status<>'pending' OR NOT public.member_is_active(auth.uid()) OR NEW.snoozed_until IS NULL OR NEW.snoozed_until<=now() OR NEW.snoozed_until>now()+interval '1 hour 1 minute') THEN RAISE EXCEPTION 'Only the recipient can snooze a pending request for one hour'; END IF; RETURN NEW; END $$;
CREATE TRIGGER standby_snooze_guard BEFORE INSERT OR UPDATE ON public.standby_swaps FOR EACH ROW EXECUTE FUNCTION public.guard_swap_snooze();